_LEDGER_STATE_KEY = "state"
_DIGEST_RE = re.compile(r"[0-9a-f]{64}\Z")


def _ledger_invalid(message: str) -> ValueError:
    return ValueError(f"invalid replication ledger: {message}")


def _state_bytes(state: dict) -> bytes:
    """Canonical compact UTF-8 bytes (one trailing LF) for a validated state."""
    clock, records = merge._validated_state(state)
    return storage._serialize(clock, records)


def _digest(payload: bytes) -> str:
    return hashlib.sha256(payload).hexdigest()


def _validated_apply_request(request: object) -> tuple[str, str, dict, dict]:
    """Validate an apply_remote request, returning (id, source, base, remote).

    The states are returned as fresh validated copies obeying the merge
    state contract.
    """
    if not isinstance(request, dict):
        raise TypeError("request must be a dict")
    if set(request.keys()) != set(_REQUEST_KEYS):
        raise ValueError(
            "request must contain exactly the keys 'id', 'source', 'base' "
            "and 'remote'"
        )
    request_id = request[ID]
    source = request[SOURCE]
    if not isinstance(request_id, str):
        raise TypeError("request id must be a str")
    if request_id == "":
        raise ValueError("request id must be non-empty")
    if not isinstance(source, str):
        raise TypeError("request source must be a str")
    if source == "":
        raise ValueError("request source must be non-empty")
    base_clock, base_records = merge._validated_state(request[BASE])
    remote_clock, remote_records = merge._validated_state(request[REMOTE])
    base = {merge.CLOCK: base_clock, merge.RECORDS: base_records}
    remote = {merge.CLOCK: remote_clock, merge.RECORDS: remote_records}
    return request_id, source, base, remote


def _request_digest(
    request_id: str, source: str, base: dict, remote: dict
) -> str:
    """Stable digest of the logical request contents."""
    ordered = {
        ID: request_id,
        SOURCE: source,
        BASE: json.loads(_state_bytes(base).decode("utf-8"))[:-1]
        if False
        else {merge.CLOCK: base[merge.CLOCK], merge.RECORDS: base[merge.RECORDS]},
        REMOTE: {merge.CLOCK: remote[merge.CLOCK], merge.RECORDS: remote[merge.RECORDS]},
    }
    payload = json.dumps(ordered, ensure_ascii=False, sort_keys=True,
                         separators=(",", ":")).encode("utf-8")
    return _digest(payload)


def _serialize_ledger(
    state: dict, requests: dict[str, str], entries: list[dict]
) -> bytes:
    ledger = {
        AUDIT: [
            {key: entry[key] for key in _LEDGER_ENTRY_KEYS} for entry in entries
        ],
        REQUESTS: dict(sorted(requests.items())),
        _LEDGER_STATE_KEY: {
            merge.CLOCK: state[merge.CLOCK],
            merge.RECORDS: state[merge.RECORDS],
        },
        _LEDGER_VERSION_KEY: LEDGER_VERSION,
    }
    text = json.dumps(
        ledger, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    ) + "\n"
    return text.encode("utf-8")


def _parse_ledger(raw: bytes) -> tuple[dict, dict[str, str], list[dict]]:
    """Validate every byte of a ledger and return (state, requests, audit).

    Raises :class:`ValueError` for any UTF-8/JSON failure, non-canonical
    encoding, wrong key set/version, an invalid state or index, or a broken
    audit chain.
    """
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _ledger_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise _ledger_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise _ledger_invalid("must be a JSON object")
    if set(data.keys()) != set(_LEDGER_KEYS):
        raise _ledger_invalid(
            "must contain exactly the keys 'audit', 'requests', 'state' "
            "and 'version'"
        )
    version = data[_LEDGER_VERSION_KEY]
    if isinstance(version, bool) or not isinstance(version, int):
        raise _ledger_invalid("version must be an int")
    if version != LEDGER_VERSION:
        raise _ledger_invalid("version must be the integer 1")

    try:
        clock, records = merge._validated_state(data[_LEDGER_STATE_KEY])
    except (TypeError, ValueError) as exc:
        raise _ledger_invalid(f"state is invalid: {exc}") from exc
    state = {merge.CLOCK: clock, merge.RECORDS: records}

    raw_requests = data[REQUESTS]
    if not isinstance(raw_requests, dict):
        raise _ledger_invalid("requests must be an object")
    requests: dict[str, str] = {}
    for key, value in raw_requests.items():
        if not isinstance(key, str) or key == "":
            raise _ledger_invalid("requests keys must be non-empty str")
        if not isinstance(value, str) or _DIGEST_RE.fullmatch(value) is None:
            raise _ledger_invalid(
                "requests values must be 64 lowercase hex characters"
            )
        requests[key] = value

    raw_entries = data[AUDIT]
    if not isinstance(raw_entries, list):
        raise _ledger_invalid("audit must be an array")
    entries: list[dict] = []
    expected_seq = 1
    expected_before = None
    for position, entry in enumerate(raw_entries):
        if not isinstance(entry, dict):
            raise _ledger_invalid(f"audit entry {position} must be an object")
        if set(entry.keys()) != set(_LEDGER_ENTRY_KEYS):
            raise _ledger_invalid(
                f"audit entry {position} must contain exactly the keys "
                "'after', 'before', 'id', 'seq' and 'source'"
            )
        after_digest = entry[AFTER]
        before_digest = entry[BEFORE]
        entry_id = entry[ID]
        seq = entry[SEQ]
        entry_source = entry[SOURCE]
        for name, value in ((AFTER, after_digest), (BEFORE, before_digest)):
            if not isinstance(value, str) or _DIGEST_RE.fullmatch(value) is None:
                raise _ledger_invalid(
                    f"audit entry {position} {name} must be 64 lowercase hex "
                    "characters"
                )
        if not isinstance(entry_id, str) or entry_id == "":
            raise _ledger_invalid(f"audit entry {position} id must be non-empty str")
        if not isinstance(entry_source, str) or entry_source == "":
            raise _ledger_invalid(
                f"audit entry {position} source must be non-empty str"
            )
        if isinstance(seq, bool) or not isinstance(seq, int):
            raise _ledger_invalid(f"audit entry {position} seq must be an int")
        if seq != expected_seq:
            raise _ledger_invalid(
                f"audit entry {position} seq is {seq}, expected {expected_seq}"
            )
        if entry_id not in requests:
            raise _ledger_invalid(
                f"audit entry {position} id {entry_id!r} is missing from requests"
            )
        if expected_before is not None and before_digest != expected_before:
            raise _ledger_invalid(
                f"audit entry {position} before does not chain to the previous after"
            )
        entries.append(
            {
                AFTER: after_digest,
                BEFORE: before_digest,
                ID: entry_id,
                SEQ: seq,
                SOURCE: entry_source,
            }
        )
        expected_seq += 1
        expected_before = after_digest

    state_digest = _digest(_state_bytes(state))
    if entries and entries[-1][AFTER] != state_digest:
        raise _ledger_invalid("last audit after must hash the stored state")
    if not entries and requests:
        raise _ledger_invalid("requests without audit entries are not allowed")

    canonical = _serialize_ledger(state, requests, entries)
    if canonical != raw:
        raise _ledger_invalid("encoding is not the canonical compact form")
    return state, requests, entries


def _read_ledger(
    path: str, base: dict
) -> tuple[dict, dict[str, str], list[dict]]:
    """Read the ledger at ``path``, defaulting a missing file to ``base``."""
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        clock, records = merge._validated_state(base)
        return {merge.CLOCK: clock, merge.RECORDS: records}, {}, []
    return _parse_ledger(raw)


def _record_decision(
    key: str, local_record: list | None, remote_record: list
) -> tuple[str, dict | None]:
    """Return (decision, need) for one key against the current local record."""
    local_clock = None
    need = merge._remote_need(remote_record, _CURRENT_CLOCK[0])
    if need:
        return "missing", need
    if local_record is None:
        return APPLY, None
    if local_record == remote_record:
        return STATUS_DUPLICATE, None
    if merge._dominates(remote_record[2], local_record[2]):
        return APPLY, None
    if merge._dominates(local_record[2], remote_record[2]):
        return STALE, None
    return CONFLICT, None


_CURRENT_CLOCK: list[dict] = [{}]


def apply_remote(path: str, request: dict) -> dict:
    """Apply one remote replication request against the ledger at ``path``.

    ``request`` must contain exactly the keys ``id`` and ``source`` (both
    non-empty str) and ``base`` and ``remote`` (states obeying the
    :mod:`~offline_coordination.merge` contract).  ``path`` is a version-1
    ledger; when it is missing the current state is taken to be ``base``
    with empty request/audit indexes, otherwise the stored ``state``,
    ``requests`` and ``audit`` are read and fully validated first.

    Remote records are inspected in ascending key order.  Each record's
    prerequisite is its clock with the ``writer`` component decremented by
    one; missing prerequisites decide ``missing`` (with ``need`` listing
    the closed intervals still required per node).  Otherwise an equal
    record is ``duplicate``, a remote-dominating record ``apply``, a
    local-dominating record ``stale`` and a concurrent record ``conflict``.

    The overall result follows the precedence ``missing``, ``conflict``,
    ``stale``, ``duplicate``, ``applied``; every outcome other than
    ``applied`` is side-effect free.  Only when at least one record
    ``apply``s and every other record is ``apply`` or ``duplicate`` are
    the records updated, the outer clock raised per node to the applied
    records, one chained audit entry appended and the request bound in
    ``requests``, all via a single atomic replacement.

    A repeated ``id`` with an identical request is ``duplicate`` and
    leaves the bytes unchanged; the same ``id`` with a different request
    raises :class:`ValueError`.  An unknown ``id`` whose current state is
    not ``base`` returns ``stale`` without writing.

    The result has the key order ``items``, ``receipt``, ``status``; each
    item has ``decision``, ``key``, ``need`` and ``receipt`` is ``None``
    unless committed.  Type violations raise :class:`TypeError`; other
    contract violations raise :class:`ValueError`; a write, replace or
    sync failure propagates as :class:`OSError` with the prior bytes
    preserved.
    """
    if not isinstance(path, str):
        raise TypeError("path must be a str")

    request_id, source, base, remote = _validated_apply_request(request)

    state, requests, entries = _read_ledger(path, base)

    if request_id in requests:
        digest = _request_digest(request_id, source, base, remote)
        if requests[request_id] != digest:
            raise ValueError(
                f"request id {request_id!r} is already bound to a different request"
            )
        state_digest = _digest(_state_bytes(state))
        result_entries = [
            entry for entry in entries if entry[ID] == request_id
        ]
        if not result_entries:
            # Indexed but never applied cannot happen through this module;
            # treat as corruption rather than silently inventing a receipt.
            raise _ledger_invalid(
                f"request id {request_id!r} is bound but has no audit entry"
            )
        entry = result_entries[-1]
        return {
            ITEMS: [],
            RECEIPT: {
                ID: request_id,
                SOURCE: source,
                BEFORE: entry[BEFORE],
                AFTER: entry[AFTER],
                SEQ: entry[SEQ],
            },
            STATUS: STATUS_DUPLICATE,
        }

    base_bytes = _state_bytes(base)
    current_bytes = _state_bytes(state)
    if current_bytes != base_bytes:
        # An unseen id must be offered against the state it claims as base.
        return {
            ITEMS: [
                {DECISION: STALE, "key": key, "need": None}
                for key in sorted(remote[merge.RECORDS])
            ],
            RECEIPT: None,
            STATUS: STALE,
        }

    _CURRENT_CLOCK[0] = state[merge.CLOCK]
    items: list[dict] = []
    decisions: list[str] = []
    for key in sorted(remote[merge.RECORDS]):
        remote_record = remote[merge.RECORDS][key]
        local_record = state[merge.RECORDS].get(key)
        decision, need = _record_decision(key, local_record, remote_record)
        items.append({DECISION: decision, "key": key, "need": need})
        decisions.append(decision)
    _CURRENT_CLOCK[0] = {}

    def overall() -> str:
        for status in ("missing", CONFLICT, STALE, STATUS_DUPLICATE, STATUS_APPLIED):
            if status in decisions:
                return status
        return STATUS_DUPLICATE

    status = overall()
    if status != STATUS_APPLIED:
        return {ITEMS: items, RECEIPT: None, STATUS: status}

    before_digest = _digest(current_bytes)
    new_clock = dict(state[merge.CLOCK])
    new_records = {
        key: [value, deleted, dict(clock), writer]
        for key, (value, deleted, clock, writer) in state[merge.RECORDS].items()
    }
    for item, key in zip(items, sorted(remote[merge.RECORDS])):
        if item[DECISION] != APPLY:
            continue
        value, deleted, clock, writer = remote[merge.RECORDS][key]
        new_records[key] = [value, deleted, dict(clock), writer]
        for node, count in clock.items():
            if count > new_clock.get(node, 0):
                new_clock[node] = count
    new_state = {merge.CLOCK: new_clock, merge.RECORDS: new_records}
    after_bytes = _state_bytes(new_state)
    after_digest = _digest(after_bytes)

    new_entries = entries + [
        {
            AFTER: after_digest,
            BEFORE: before_digest,
            ID: request_id,
            SEQ: len(entries) + 1,
            SOURCE: source,
        }
    ]
    new_requests = dict(requests)
    new_requests[request_id] = _request_digest(request_id, source, base, remote)

    payload = _serialize_ledger(new_state, new_requests, new_entries)
    tmp_path = path + ".tmp"
    existed = os.path.exists(path)
    try:
        with open(tmp_path, "wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, path)
        fd = os.open(os.path.dirname(os.path.abspath(path)), os.O_RDONLY)
        try:
            os.fsync(fd)
        finally:
            os.close(fd)
    except OSError:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise

    return {
        ITEMS: items,
        RECEIPT: {
            ID: request_id,
            SOURCE: source,
            BEFORE: before_digest,
            AFTER: after_digest,
            SEQ: len(entries) + 1,
        },
        STATUS: STATUS_APPLIED,
    }

toolUseResult.newString:
