APPLY = "apply"
CONFLICT = "conflict"
DECISION = "decision"
ITEMS = "items"
RECEIPT = "receipt"
STALE = "stale"

APPLY_REMOTE = "apply_remote"
AUDIT = "audit"
BASE = "base"
BEFORE = "before"
AFTER = "after"
ID = "id"
REMOTE = "remote"
REQUESTS = "requests"
SOURCE = "source"
SEQ = "seq"

LEDGER_VERSION = 1
_LEDGER_KEYS = (AUDIT, REQUESTS, merge.CLOCK if False else "state", "version")
_REQUEST_KEYS = (ID, SOURCE, BASE, REMOTE)
_LEDGER_ENTRY_KEYS = (AFTER, BEFORE, ID, SEQ, SOURCE)
_LEDGER_VERSION_KEY = "version"
_LEDGER_STATE_KEY = "state"
_DIGEST_RE = re.compile(r"[0-9a-f]{64}\Z")


def _ledger_invalid(message: str) -> ValueError:
