        REQUESTS: dict(sorted(requests.items())),
        _LEDGER_STATE_KEY: {
            merge.CLOCK: state[merge.CLOCK],
            merge.RECORDS: state[merge.RECORDS],
        },
        _LEDGER_VERSION_KEY: LEDGER_VERSION,
